mapper.select:
select r.item_id, sum(r.qty) as qty
  from () r
 where r.plant_cd = #{plantCd}
   and r.item_id in #{id}
 group by r.item_id
having sum(r.qty) > 0

select r.rtn_id, r.rtn_no, r.status, c.cust_cd, c.cust_nm, i.item_cd, i.item_nm, lm.lot_no, r.qty, r.unit_cd, r.reason_cd,
       r.ncr_id, r.ncr_no, r.capa_no, r.received_at
  from wms_cust_rtn r
  join mst_cust c on c.cust_id = r.cust_id
  join mst_item i on i.item_id = r.item_id
  left join lot_master lm on lm.lot_id = r.lot_id


     btrim(r.capa_no) = #{capaNo}

       or r.ncr_id in #{id}



 order by r.received_at desc, r.rtn_id desc
 limit #{limit}
